import 'package:flutter/material.dart';void main() {  runApp(const MyApp());}class MyApp extends StatelessWidget {  const MyApp({Key? key}) : super(key: key);  @override  Widget build(BuildContext context) {    return const MaterialApp(      title: 'Simple Calculator',      home: Calculator(),    );  }}class Calculator extends StatefulWidget {  const Calculator({Key? key}) : super(key: key);  @override  State<Calculator> createState() => _CalculatorState();}class _CalculatorState extends State<Calculator> {  final _textController = TextEditingController();  double? _result;  void _calculate(String operation) {    final text = _textController.text;    if (text.isEmpty) return;    final parts = text.split('+');    if (operation == '+') {      if (parts.length == 2) {        final num1 = double.parse(parts[0]);        final num2 = double.parse(parts[1]);        setState(() {          _result = num1 + num2;        });      }    }    final partsSub = text.split('-');    if (operation == '-') {      if (partsSub.length == 2) {        final num1 = double.parse(partsSub[0]);        final num2 = double.parse(partsSub[1]);        setState(() {          _result = num1 - num2;        });      }    }    final partsMul = text.split('*');    if (operation == '*') {      if (partsMul.length == 2) {        final num1 = double.parse(partsMul[0]);        final num2 = double.parse(partsMul[1]);        setState(() {          _result = num1 * num2;        });      }    }    final partsDiv = text.split('/');    if (operation == '/') {      if (partsDiv.length == 2) {        final num1 = double.parse(partsDiv[0]);        final num2 = double.parse(partsDiv[1]);        if (num2 != 0) {          setState(() {            _result = num1 / num2;          });        }      }    }  }  @override  Widget build(BuildContext context) {    return Scaffold(      appBar: AppBar(        title: const Text('Simple Calculator'),      ),      body: Padding(        padding: const EdgeInsets.all(16.0),        child: Column(          children: [            TextField(              controller: _textController,              decoration: const InputDecoration(                border: OutlineInputBorder(),                labelText: 'Enter numbers and operation',              ),            ),            const SizedBox(height: 16),            ElevatedButton(              onPressed: () => _calculate('+'),              child: const Text('+'),            ),            const SizedBox(height: 8),            ElevatedButton(              onPressed: () => _calculate('-'),              child: const Text('-'),            ),            const SizedBox(height: 8),            ElevatedButton(              onPressed: () => _calculate('*'),              child: const Text('*'),            ),            const SizedBox(height: 8),            ElevatedButton(              onPressed: () => _calculate('/'),              child: const Text('/'),            ),            const SizedBox(height: 16),            Text(_result != null ? 'Result: $_result' : 'Result: '),          ],        ),      ),    );  }}